(function(){
 'use strict';
 const $=id=>document.getElementById(id),cfg=globalThis.CAMPUS_CONFIG||{},A=CampusAuthCore,Core=CampusAdminCore;
 const ready=location.protocol!=='file:'&&A.configReady(cfg),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let backend;try{backend=new CampusBackend(cfg,fetch.bind(globalThis),sessionStorage);}catch{backend=new CampusBackend(cfg,fetch.bind(globalThis),null);}
 let lang='zh',preview=false,busy=false,after='',overview=null,email='',exports=[],epoch=0,messageKey='',appliedFilters={};
 const t=k=>CAMPUS_ADMIN_TEXT[lang][k]||k,num=n=>n===null||n===undefined?'—':new Intl.NumberFormat(lang==='zh'?'zh-CN':lang==='ur'?'ur-PK':'en-US',{maximumFractionDigits:2}).format(n);
 const stamp=v=>v?new Date(v).toISOString().replace('T',' ').replace(/\.\d+Z$/,' UTC'):'—';
 const filters=()=>({condition:$('conditionFilter').value,status:$('statusFilter').value,university:$('schoolFilter').value.trim(),from:$('fromFilter').value,to:$('toFilter').value});
 $('studyId').value=cfg.studyId||'almab-factorial-test-v4';
 for(let i=0;i<8;i++){const option=document.createElement('option');option.value=i.toString(2).padStart(3,'0');option.textContent='P'+option.value[0]+' · O'+option.value[1]+' · L'+option.value[2];$('conditionFilter').append(option);}
 function setMessage(key){messageKey=key;$('message').textContent=key?t(key):'';}
 function texts(){
  document.documentElement.lang=lang==='zh'?'zh-CN':lang;document.documentElement.dir=lang==='ur'?'rtl':'ltr';document.title='Campus Shelf · '+t('title');
  document.querySelectorAll('[data-text]').forEach(el=>el.textContent=t(el.dataset.text));document.querySelectorAll('[data-lang]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.lang===lang)));
  $('message').textContent=messageKey?t(messageKey):'';
  $('connectionBadge').textContent=t(preview?'previewBadge':ready?'configured':'notConnected');$('setupNotice').textContent=t(preview||!ready?'setup':overview?.synthetic?'syntheticNotice':'connectedSetup');
  $('emailForm').querySelector('button').disabled=!ready||busy;
  if(overview)render();
 }
 async function run(key,fn){if(busy)return;busy=true;const currentEpoch=epoch;setMessage(key);document.querySelectorAll('#authPanel button,#refresh,[data-export],#filters button,#signOut,#nextPage,#firstPage').forEach(b=>b.disabled=true);
  try{await fn();if(currentEpoch===epoch&&$('message').textContent===t(key))setMessage('');}
  catch(e){if(currentEpoch===epoch){if(['adminRequired','sessionExpired'].includes(e.message)){overview=null;$('dashboard').hidden=true;$('authPanel').hidden=false;$('participantRows').innerHTML='';$('detailDialog').close();$('detailContent').innerHTML='';exports=[];backend.remember(null);}setMessage(e.message in CAMPUS_ADMIN_TEXT.en?e.message:'error');}}
  finally{busy=false;document.querySelectorAll('#authPanel button,#refresh,#filters button,#signOut,#nextPage,#firstPage').forEach(b=>b.disabled=false);texts();}
 }
 function conditionText(code){const rate=overview?.base_config?.markupPercent||25;return [code[0]==='1'?t('markup').replace('25',String(rate)):t('original'),t(code[1]==='1'?'optimized':'control'),t(code[2]==='1'?'labels':'noLabels')].join(' · ');}
 function render(){
  const groups=overview.groups,allocated=groups.reduce((n,g)=>n+g.allocated,0),completed=groups.reduce((n,g)=>n+g.completed,0);
  $('metrics').innerHTML=[['allocated',allocated],['finished',completed],['unfinished',allocated-completed]].map(([label,n])=>`<div class="metric"><span>${t(label)}</span><strong>${num(n)}</strong></div>`).join('');
  $('studyMeta').textContent=`${overview.study_id} · ${t('protocol')}: ${overview.protocol_version} · ${t('enrollment')}: ${t(overview.enrollment_open?'open':'closed')} · ${t('tasks')}: ${t(overview.tasks_open?'open':'closed')} · ${t('catalogVersion')}: ${overview.catalog_version||'—'}`;
  $('groupGrid').innerHTML=groups.map(g=>`<article class="group-card"><span class="group-code" dir="ltr">P${g.condition_code[0]} O${g.condition_code[1]} L${g.condition_code[2]}</span><p>${esc(conditionText(g.condition_code))}</p><div class="group-count"><span><b>${num(g.allocated)}</b>${t('allocated')}</span><span><b>${num(g.completed)}</b>${t('finished')}</span></div></article>`).join('');
  $('recordCount').textContent=`${num(overview.total)} ${t('rows')}`;
  $('participantRows').innerHTML=overview.rows.length?overview.rows.map(r=>`<tr><td><bdi dir="ltr" title="${esc(r.participant_id)}">${esc(preview?r.participant_id:r.participant_id.slice(0,8)+'…')}</bdi></td><td><bdi dir="ltr">${esc(r.condition_code)}</bdi></td><td>${esc(r.university)}</td><td><span class="status ${r.status==='completed'?'complete':''}">${t(r.status)}</span></td><td>${num(r.amount_pkr)}</td><td>${num(r.upf_energy_kcal)}</td><td><button class="detail-button" data-task="${esc(r.task_id)}">${t('detail')}</button></td></tr>`).join(''):`<tr><td colspan="7" class="empty-state">${t('empty')}</td></tr>`;
  $('pageNote').textContent=`${t('loaded')}: ${num(overview.rows.length)}`;$('nextPage').disabled=busy||overview.rows.length<50;$('firstPage').disabled=busy||!after;
  document.querySelectorAll('[data-export]').forEach(b=>{b.disabled=busy||!overview.can_export;b.title=overview.can_export?'':t('noExport');});$('refresh').disabled=busy;$('signOut').disabled=busy;$('filters').querySelector('button').disabled=busy;
 }
 const sampleRows=()=>Array.from({length:16},(_,i)=>{const condition=Math.floor(i/2).toString(2).padStart(3,'0'),completed=i%2===0,empty=i===0;return {row_id:String(i+1).padStart(4,'0'),study_id:'SAMPLE-ONLY',participant_id:`SAMPLE-${String(i+1).padStart(4,'0')}`,task_id:`SAMPLE-TASK-${i+1}`,condition_code:condition,price_factor:+condition[0],position_factor:+condition[1],label_factor:+condition[2],markup_percent:25,layout_mode:condition[1]==='1'?'alternatives-eye':'targets-eye',placement_rule:'upf-or-high',budget_pkr:600,assigned_at:'2026-10-24T12:00:00.000Z',started_at:'2026-10-24T12:00:00.000Z',completed_at:completed?'2026-10-24T12:08:00.000Z':null,status:completed?'completed':'in_progress',language:'en',age_at_registration:21+i%3,gender:'prefer_not_to_say',university:i%2?'Sample University B':'Sample University A',height_cm:170,weight_kg:65,waist_cm:78,questionnaire_code:null,questionnaire_link_status:'not_provided',quantity:completed?(empty?0:2):null,amount_pkr:completed?(empty?0:condition[0]==='1'?185:160):null,energy_kcal:completed?(empty?0:138.6):null,upf_energy_kcal:completed?(empty?0:138.6):null,unknown_energy_kcal:completed?0:null,upf_energy_share:completed&&!empty?1:null,protocol_version:'SAMPLE-PROTOCOL',catalog_version:CAMPUS_DATA.version,rules_version:CampusShelfCore.RULES_VERSION,layout_version:CampusShelfCore.LAYOUT_VERSION,synthetic:true};});
 function sampleOverview(f=filters()){const rows=sampleRows(),matches=rows.filter(r=>(!f.condition||r.condition_code===f.condition)&&(!f.status||r.status===f.status)&&(!f.university||r.university.toLowerCase().includes(f.university.toLowerCase()))&&(!f.from||r.assigned_at.slice(0,10)>=f.from)&&(!f.to||r.assigned_at.slice(0,10)<=f.to));return {study_id:'SAMPLE-ONLY',protocol_version:'SAMPLE-PROTOCOL',catalog_version:CAMPUS_DATA.version,synthetic:true,base_config:{markupPercent:25},enrollment_open:false,tasks_open:false,can_export:true,groups:Array.from({length:8},(_,i)=>({condition_code:i.toString(2).padStart(3,'0'),allocated:2,completed:1})),total:matches.length,rows:matches.filter(r=>r.row_id>after).slice(0,50)};}
 async function load(){const currentEpoch=epoch,f=filters();const data=preview?sampleOverview(f):await backend.overview($('studyId').value.trim(),f,after);if(currentEpoch!==epoch)return;overview=data;appliedFilters=f;$('dashboard').hidden=false;$('authPanel').hidden=true;texts();}
 function download(content,name,type='text/csv;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 async function exportData(dataset){
  let rows=[],metadata;const scope={...appliedFilters};
  if(preview){const previous=after;after='';const selected=sampleOverview(scope).rows;after=previous;rows=dataset==='participants'?selected:dataset==='catalog'?CAMPUS_DATA.products:[];metadata={study_id:'SAMPLE-ONLY',dataset,cutoff:new Date().toISOString(),sample:true};}
  else{metadata=await backend.startExport(overview.study_id,dataset,scope);let key='';for(;;){const page=await backend.exportPage(metadata.export_id,key);rows.push(...page.rows);if(rows.length>100000)throw new Error('exportLimit');if(!page.next)break;if(page.next===key)throw new Error('serviceError');key=page.next;}}
  const file=`${preview?'SAMPLE_':''}campus-shelf_${dataset}_${new Date().toISOString().replace(/[:.]/g,'-')}.csv`;download(Core.csv(rows,dataset),file);exports.push({...metadata,file,row_count:rows.length,filters:scope});setMessage('exported');
 }
 function manifest(){if(!exports.length){setMessage('noManifest');return;}download(JSON.stringify({format:'campus-shelf-admin-export-v1',interface_version:'0.10.0',generated_at:new Date().toISOString(),sample:preview,synthetic:overview.synthetic,study_id:overview.study_id,protocol_version:overview.protocol_version,catalog_version:overview.catalog_version,rules_version:overview.rules_version,layout_version:overview.layout_version,base_config:overview.base_config,randomization:overview.randomization,files:exports,notes:['Each file uses its own server cutoff timestamp; do not assume separate exports are one database transaction.','Incomplete outcomes are blank; a completed empty basket has zero energy and undefined UPF energy share.','Unknown NOVA energy makes UPF energy share undefined.','Client interaction times are untrusted; visibility is not eye tracking.','CSV protects formula-like strings with a leading apostrophe. Contacts and DOB are excluded.','Questionnaire codes require verification before matching.']},null,2),`${preview?'SAMPLE_':''}campus-shelf_export-manifest.json`,'application/json');}
 async function detail(id){
  let data;if(preview){const r=sampleRows().find(r=>r.task_id===id);data={participant:r,config:{schemaVersion:2,budget:600,price:!!r.price_factor,position:!!r.position_factor,labels:!!r.label_factor,upf:!!r.label_factor,markupPercent:25,layoutMode:r.layout_mode,placementRule:r.placement_rule},products:CAMPUS_DATA.products,items:r.quantity?[{product_id:'cola',quantity:1,unit_price_pkr:r.price_factor?125:100,line_total_pkr:r.price_factor?125:100,energy_kcal:138.6},{product_id:'water',quantity:1,unit_price_pkr:60,line_total_pkr:60,energy_kcal:0}]:[]};}else data=await backend.taskDetail(id);
  const r=data.participant,fields=[['participant',r.participant_id],['condition',conditionText(r.condition_code)],['university',r.university],['age',r.age_at_registration],['gender',r.gender],['height',r.height_cm],['weight',r.weight_kg],['waist',r.waist_cm],['questionnaire',r.questionnaire_code||'—'],['assignedAt',stamp(r.assigned_at)],['completedAt',stamp(r.completed_at)],['catalogVersion',r.catalog_version]];
  $('detailContent').innerHTML=`<div class="detail-meta">${fields.map(([k,v])=>`<div><strong>${t(k)}</strong>${esc(v)}</div>`).join('')}</div><p class="notice">${t(r.status!=='completed'?'notCompleted':data.items.length?'completed':'noPurchase')}</p>${data.items.length?`<div class="table-wrap"><table><thead><tr>${['product','quantity','unitPrice','lineTotal','energy'].map(k=>`<th>${t(k)}</th>`).join('')}</tr></thead><tbody>${data.items.map(item=>{const p=data.products.find(p=>p.id===item.product_id);return `<tr><td>${esc(p?.[lang]||p?.en||item.product_id)}</td><td>${num(item.quantity)}</td><td>${num(item.unit_price_pkr)}</td><td>${num(item.line_total_pkr)}</td><td>${num(item.energy_kcal)}</td></tr>`;}).join('')}</tbody></table></div>`:''}`;
  $('detailDialog').showModal();
 }
 document.addEventListener('click',e=>{const l=e.target.closest('[data-lang]');if(l){lang=l.dataset.lang;texts();return;}const task=e.target.closest('[data-task]');if(task){run('loading',()=>detail(task.dataset.task));return;}const exp=e.target.closest('[data-export]');if(exp)run('exporting',()=>exportData(exp.dataset.export));});
 $('emailForm').addEventListener('submit',e=>{e.preventDefault();email=$('adminEmail').value.trim();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){setMessage('invalidContact');return;}run('sending',async()=>{await backend.send('email',email,false);$('codeForm').hidden=false;setMessage('sent');$('adminCode').focus();});});
 $('codeForm').addEventListener('submit',e=>{e.preventDefault();run('working',async()=>{await backend.verify('email',email,A.digits($('adminCode').value));preview=false;after='';await load();$('adminCode').value='';});});
 $('previewAdmin').addEventListener('click',()=>{preview=true;after='';exports=[];run('loading',load);});
 $('refresh').addEventListener('click',()=>{after='';exports=[];run('loading',load);});$('filters').addEventListener('submit',e=>{e.preventDefault();after='';run('loading',load);});
 $('firstPage').addEventListener('click',()=>{after='';run('loading',load);});$('nextPage').addEventListener('click',()=>{after=overview.rows.at(-1)?.row_id||'';run('loading',load);});
 $('signOut').addEventListener('click',()=>run('working',async()=>{try{if(!preview)await backend.signOut();}finally{epoch++;preview=false;overview=null;exports=[];after='';appliedFilters={};$('dashboard').hidden=true;$('authPanel').hidden=false;$('codeForm').hidden=true;$('adminCode').value='';$('adminEmail').value='';email='';for(const id of ['participantRows','detailContent','groupGrid','metrics','studyMeta','recordCount'])$(id).innerHTML='';$('detailDialog').close();setMessage('');}}));
 $('dictionary').addEventListener('click',()=>download(Core.dictionary(),'campus-shelf_data-dictionary.csv'));$('manifest').addEventListener('click',manifest);$('closeDetail').addEventListener('click',()=>$('detailDialog').close());
 texts();if(ready&&backend.session)run('loading',load);
})();
